import sys

MOD = 1_000_000_007

def fib(n: int) -> int:
    if n <= 0:
        return 0
    a, b = 0, 1
    # Fast doubling top-down using bit_length
    for i in range(n.bit_length() - 1, -1, -1):
        # c = F(2k) = F(k) * (2*F(k+1) - F(k))
        # d = F(2k+1) = F(k)^2 + F(k+1)^2
        c = (a * ((b << 1) - a)) % MOD
        d = (a * a + b * b) % MOD
        if (n >> i) & 1:
            a, b = d, (c + d) % MOD
        else:
            a, b = c, d
    return a

if __name__ == "__main__":
    if len(sys.argv) > 1:
        print(fib(int(sys.argv[1])))
